  return `<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.55;color:#111827;max-width:560px">\n${textToHtml(bodyText)}\n${button}${foot}\n</div>`;
